function outputFile = routeA_focused_export_validation_json(outputFile)
% Export the current 52-case V-SH validation MAT evidence for the workbook.
%
% This is a report-data adapter only. It does not alter the model or rerun
% any case. All numerical fields are read from the current-topology MAT
% files generated by run_routeA_focused_study.

if nargin < 1 || strlength(string(outputFile)) == 0
    outputFile = fullfile(fileparts(mfilename('fullpath')), '..', '..', ...
        '02_结果', 'RouteA_Cathode_cEGR_Focused', 'outputs', ...
        '20260820_vsh_validation', ...
        'RouteA_VSH_validation_rows_20260820.json');
end
outputFile = char(outputFile);

matFiles = { ...
    fullfile(fileparts(mfilename('fullpath')), '..', '..', ...
        '02_结果', 'RouteA_Cathode_cEGR_Focused', 'outputs', ...
        '20260820_vsh_validation', ...
        'RouteA_Focused_External240kW_VSH_PassiveCEGR_total_flow_fixed_4J_600s_20260820.mat'), ...
    fullfile(fileparts(mfilename('fullpath')), '..', '..', ...
        '02_结果', 'RouteA_Cathode_cEGR_Focused', 'outputs', ...
        '20260820_vsh_validation', ...
        'RouteA_Focused_External240kW_VSH_PassiveCEGR_fresh_air_fixed_4J_600s_20260820.mat')};

rows = repmat(rowTemplate(), 0, 1);
summaries = repmat(summaryTemplate(), 0, 1);
for fileIndex = 1:numel(matFiles)
    sourceFile = matFiles{fileIndex};
    if ~isfile(sourceFile)
        error('RouteA:FocusedValidationExportFile', ...
            'Validation MAT file is missing: %s', sourceFile);
    end
    data = load(sourceFile, 'routeA_focused_study');
    study = data.routeA_focused_study;
    if ~isfield(study, 'cegrScreenAudit') || ...
            ~isfield(study.cegrScreenAudit, 'rows')
        error('RouteA:FocusedValidationExportAudit', ...
            'MAT file has no current cEGR screening audit rows: %s', sourceFile);
    end
    auditRows = study.cegrScreenAudit.rows;
    for caseIndex = 1:numel(study.cases)
        item = study.cases(caseIndex);
        audit = auditRows(caseIndex);
        rows(end + 1) = makeRow(item, audit, sourceFile, study); %#ok<AGROW>
    end
    summaries(end + 1) = makeSummary(study, auditRows, sourceFile); %#ok<AGROW>
end

payload = struct( ...
    'schemaVersion', "RouteA_VSH_ValidationWorkbookData_v01", ...
    'generatedAt', string(datetime('now', 'Format', ...
        'yyyy-MM-dd HH:mm:ss')), ...
    'model', "PEMFuelCellSystem_Cathode_cEGR_SelfHumidifying_v01", ...
    'runner', "run_routeA_focused_study", ...
    'topology', "VSH_StackOutletIdealSplit_TwoValve_v01", ...
    'scope', "gas_phase_model_and_interface_behavior_only", ...
    'rows', rows, ...
    'summaries', summaries, ...
    'fieldContract', fieldContract());

resultDirectory = fileparts(outputFile);
if ~isfolder(resultDirectory)
    mkdir(resultDirectory);
end
fid = fopen(outputFile, 'w', 'n', 'UTF-8');
if fid < 0
    error('RouteA:FocusedValidationExportOpen', ...
        'Could not open JSON output file: %s', outputFile);
end
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fprintf(fid, '%s', jsonencode(payload, 'PrettyPrint', true));
end

function row = makeRow(item, audit, sourceFile, study)
performance = getField(item, 'performance', struct());
electrical = getField(performance, 'electrical', struct());
cegr = getField(performance, 'cegr', struct());
pressure = getField(performance, 'pressure', struct());
chain = getField(pressure, 'chain', struct());
anti = getField(performance, 'antiCondensation', struct());
mixer = getField(anti, 'mixer', struct());
caseCfg = getField(item, 'caseCfg', struct());
caseId = string(getField(item, 'caseId', ""));
if contains(caseId, "total_flow_fixed")
    strategy = "total_flow_fixed";
else
    strategy = "fresh_air_fixed";
end

row = rowTemplate();
row.strategy = strategy;
row.caseId = caseId;
row.simCompleted = logical(getField(item, 'simCompleted', false));
row.localNumericsPassed = logical(getField(item, 'passed', false));
row.currentDensity_A_cm2 = getNested(caseCfg, ...
    {'external240ReferenceCurrentDensity_A_cm2'}, NaN);
row.referenceOER = getNested(caseCfg, {'air', 'targetOer'}, NaN);
row.targetRecirculationR = getNested(caseCfg, ...
    {'cegr', 'targetRecirculationR'}, NaN);
row.actualRecirculationR = getField(audit, ...
    'actualRecirculationR', NaN);
row.recirculationError = getField(audit, 'recirculationError', NaN);
row.recirculationTolerance = getField(audit, ...
    'recirculationTrackingTolerance', NaN);
row.targetMixFraction = getNested(caseCfg, {'cegr', 'targetRatio'}, NaN);
row.actualMixFraction = getField(audit, 'actualMixFraction', NaN);
row.rSplit = getField(audit, 'actualRSplit', NaN);
row.returnMdot_kg_s = getField(cegr, 'splitReturnMdot_kg_s', NaN);
row.freshMdot_kg_s = getField(cegr, 'freshAirApprox_kg_s', NaN);
row.exhaustMdot_kg_s = getField(cegr, 'splitExhaustMdot_kg_s', NaN);
row.actualOERMean = getField(audit, 'actualOERMean', NaN);
row.actualOERMinimum = getField(audit, 'actualOERMinimum', NaN);
row.oerStatus = string(getField(audit, 'actualOERStatus', ""));
row.cellVoltage_V = getField(electrical, 'cellVoltage_V', NaN);
row.valveAreaFraction = getField(cegr, 'valveAreaFraction', NaN);
row.valveDeltaP_kPa = 1000 * getField(cegr, 'valveDeltaP_MPa', NaN);
row.p_comp_in_kPa = 1000 * getField(chain, 'p_comp_in_MPa', NaN);
row.p_comp_out_kPa = 1000 * getField(chain, ...
    'compressorDischargePressure_MPa', NaN);
row.p_after_intercooler_kPa = 1000 * getField(chain, ...
    'compressorAfterIntercoolerPressure_MPa', NaN);
row.p_ca_channel_kPa = 1000 * getField(chain, ...
    'stackCathodeChannelPressure_MPa', NaN);
row.p_bp_target_kPa = 1000 * getField(audit, 'p_bp_target_MPa', NaN);
row.p_stack_out_kPa = 1000 * getField(chain, 'p_stack_out_MPa', NaN);
row.p_split_kPa = 1000 * getField(chain, 'p_split_MPa', NaN);
row.p_EGR_up_kPa = 1000 * getField(chain, 'p_EGR_up_MPa', NaN);
row.p_EGR_down_kPa = 1000 * getField(chain, 'p_EGR_down_MPa', NaN);
row.p_ambient_kPa = 1000 * getField(chain, 'p_ambient_MPa', NaN);
row.deltaP_EGR_kPa = 1000 * getField(chain, 'deltaP_EGR_MPa', NaN);
row.deltaP_BP_kPa = 1000 * getField(chain, 'deltaP_BP_MPa', NaN);
row.deltaP_path_kPa = 1000 * getField(chain, 'deltaP_path_MPa', NaN);
row.stackOutSplitError_kPa = 1000 * getField(chain, ...
    'p_stack_out_to_split_error_MPa', NaN);
row.splitEGRUpError_kPa = 1000 * getField(chain, ...
    'p_split_to_EGR_up_error_MPa', NaN);
row.EGRDownCompInError_kPa = 1000 * getField(chain, ...
    'p_EGR_down_to_comp_in_error_MPa', NaN);
row.inletRH = getField(audit, 'cathodeInletRH', NaN);
row.compressorInletPO2_kPa = getField(audit, ...
    'compressorInletPO2_Pa', NaN) / 1000;
row.mixerTemperature_C = getField(mixer, 'temperature_C', NaN);
row.mixerDewMargin_C = getField(audit, 'mixerDewPointMargin_C', NaN);
row.mixerSaturation = getField(audit, 'mixerSaturationRatio', NaN);
row.mixerCondensationRate_kg_s = getField(audit, ...
    'mixerCondensationRate_kg_s', NaN);
row.mixerCondensationIntegral_kg = getField(audit, ...
    'mixerCondensationIntegral_kg', NaN);
row.mixerPhase = string(getField(audit, 'mixerCondensationStatus', ""));
row.cathodeSaturation = getField(audit, 'cathodeGasSaturationRatio', NaN);
row.cathodeCondensationRate_kg_s = getField(audit, ...
    'cathodeGasCondensationRate_kg_s', NaN);
row.cathodePhase = string(getField(audit, ...
    'cathodeGasCondensationStatus', ""));
row.returnSaturation = NaN;
row.returnCondensationRate_kg_s = NaN;
row.returnPhase = string(getField(audit, ...
    'cegrBranchCondensationStatus', ""));
row.trackingStatus = string(getField(audit, 'controlTrackingStatus', ""));
row.screeningStatus = string(getField(audit, 'caseScreenStatus', ""));
row.errorId = string(getField(item, 'errorId', ""));
row.failureCategory = string(getField(item, 'failureCategory', ""));
row.failureReason = compactFailureReason(getField(item, ...
    'errorMessage', ""), row.failureCategory);
row.sourceMat = string(sourceFile);
row.modelChecksum = checksumText(study);
end

function summary = makeSummary(study, auditRows, sourceFile)
summary = summaryTemplate();
summary.strategy = string(getNested(study.cases(1), ...
    {'caseCfg', 'flowControlPolicy'}, ""));
if contains(summary.strategy, "total_compressor")
    summary.strategy = "total_flow_fixed";
else
    summary.strategy = "fresh_air_fixed";
end
summary.sourceMat = string(sourceFile);
summary.requestedCount = numel(study.cases);
summary.completedCount = sum([auditRows.simCompleted]);
summary.localPassedCount = sum([auditRows.localNumericsPassed]);
summary.engineeringPassedCount = sum(string({auditRows.caseScreenStatus}) == ...
    "candidate_feasible_gas_phase_screen");
summary.oxygenSupplyFailureCount = sum( ...
    string({study.cases.failureCategory}) == ...
    "oxygen_supply_mass_fraction_nonnegative");
summary.valveAreaFailureCount = sum( ...
    string({auditRows.controlTrackingStatus}) == ...
    "deviation_valve_area_saturated");
summary.trackingFailureCount = sum(contains( ...
    string({auditRows.controlTrackingStatus}), "deviation"));
summary.condensationRiskCount = sum( ...
    string({auditRows.mixerCondensationStatus}) == ...
    "condensing_or_supersaturated");
summary.matrixComplete = logical(study.execution.matrixComplete);
summary.preflightStatus = string(study.preflight.status);
summary.checksum = checksumText(study);
end

function value = compactFailureReason(message, category)
if strlength(string(category)) == 0
    value = "";
    return;
end
text = replace(string(message), newline, " ");
text = replace(text, char(13), " ");
text = regexprep(text, '<[^>]*>', '');
text = strtrim(text);
if strlength(text) > 500
    text = extractBefore(text, 501) + "...";
end
if strlength(text) == 0
    text = string(category);
end
value = text;
end

function text = checksumText(study)
text = "";
if ~isfield(study, 'preflight') || ...
        ~isfield(study.preflight, 'modelChecksum')
    return;
end
text = strjoin(string(dec2hex(uint32(study.preflight.modelChecksum), 8)), '-');
end

function value = fieldContract()
value = struct( ...
    'pressureUnit', "kPa abs", ...
    'pressureDropUnit', "kPa", ...
    'flowUnit', "kg/s", ...
    'pressureSource', ...
        "performance.pressure.chain from current-topology MAT", ...
    'pressureLocations', ...
        "p_stack_out=cathode outlet chamber; p_split=ideal tee; p_EGR_up/down=cEGR valve ports; p_comp_in=compressor inlet mixer; p_ambient=environment reservoir", ...
    'rDefinition', "R_EGR=m_return/m_fresh", ...
    'xDefinition', "x_EGR=m_return/m_total=R_EGR/(1+R_EGR)", ...
    'rSplitDefinition', ...
        "m_return/(m_return+m_exhaust) at the modeled ideal split", ...
    'scope', ...
        "gas phase model and interface behavior; no liquid inventory, droplet transport, separator efficiency, compressor wet-gas tolerance, valve DN/Cv/Kv, or net-power claim");
end

