value = struct( ...
    'strategy', "", 'caseId', "", 'simCompleted', false, ...
    'localNumericsPassed', false, 'currentDensity_A_cm2', NaN, ...
    'referenceOER', NaN, 'targetRecirculationR', NaN, ...
    'actualRecirculationR', NaN, 'recirculationError', NaN, ...
    'recirculationTolerance', NaN, 'targetMixFraction', NaN, ...
    'actualMixFraction', NaN, 'rSplit', NaN, ...
    'returnMdot_kg_s', NaN, 'freshMdot_kg_s', NaN, ...
    'exhaustMdot_kg_s', NaN, 'actualOERMean', NaN, ...
    'actualOERMinimum', NaN, 'oerStatus', "", 'cellVoltage_V', NaN, ...
    'valveAreaFraction', NaN, 'valveDeltaP_kPa', NaN, ...
    'p_comp_in_kPa', NaN, 'p_comp_out_kPa', NaN, ...
    'p_after_intercooler_kPa', NaN, 'p_ca_channel_kPa', NaN, ...
    'p_bp_target_kPa', NaN, 'p_stack_out_kPa', NaN, ...
    'p_split_kPa', NaN, 'p_EGR_up_kPa', NaN, ...
    'p_EGR_down_kPa', NaN, 'p_ambient_kPa', NaN, ...
    'deltaP_EGR_kPa', NaN, 'deltaP_BP_kPa', NaN, ...
    'deltaP_path_kPa', NaN, 'stackOutSplitError_kPa', NaN, ...
    'splitEGRUpError_kPa', NaN, 'EGRDownCompInError_kPa', NaN, ...
    'inletRH', NaN, 'compressorInletPO2_kPa', NaN, ...
    'mixerTemperature_C', NaN, 'mixerDewMargin_C', NaN, ...
    'mixerSaturation', NaN, 'mixerCondensationRate_kg_s', NaN, ...
    'mixerCondensationIntegral_kg', NaN, 'mixerPhase', "", ...
    'cathodeSaturation', NaN, 'cathodeCondensationRate_kg_s', NaN, ...
    'cathodePhase', "", 'returnSaturation', NaN, ...
    'returnCondensationRate_kg_s', NaN, 'returnPhase', "", ...
    'trackingStatus', "", 'screeningStatus', "", 'errorId', "", ...
    'failureCategory', "", 'failureReason', "", 'sourceMat', "", ...
    'modelChecksum', "");
end

function value = summaryTemplate()
value = struct( ...
    'strategy', "", 'sourceMat', "", 'requestedCount', 0, ...
    'completedCount', 0, 'localPassedCount', 0, ...
    'engineeringPassedCount', 0, 'oxygenSupplyFailureCount', 0, ...
    'valveAreaFailureCount', 0, 'trackingFailureCount', 0, ...
    'condensationRiskCount', 0, 'matrixComplete', false, ...
    'preflightStatus', "", 'checksum', "");
end

function value = getField(source, name, default)
if isstruct(source) && isfield(source, name) && ~isempty(source.(name))
    value = source.(name);
else
    value = default;
end
end

function value = getNested(source, path, default)
value = source;
for idx = 1:numel(path)
    if ~isstruct(value) || ~isfield(value, path{idx}) || ...
            isempty(value.(path{idx}))
        value = default;
        return;
    end
    value = value.(path{idx});
end
end
